mapper.select:
select * from ( select row_number() over (order by allowg_id) as rn , allowg_id, allowg_name , ag.grade_id, grade_Name from allow_grade ag left join grade g on ag.grade_id = g.grade_id
where allowg_name like '%'||#{searchWord}||'%'
) as sub where rn between #{startRow} and #{endRow}

mapper.update:
update allow_grade 
set allowg_name=#{allowgName}
, grade_id=#{gradeId}
where allowg_id=#{allowgId}
